SELECT COUNT(*) AS dup_ticket FROM (
  SELECT ss_ticket_number FROM store_sales GROUP BY ss_ticket_number HAVING COUNT(DISTINCT ss_item_sk) <> COUNT(*)
) x

SELECT COUNT(*) AS total_rows, COUNT(DISTINCT i_item_sk) AS distinct_items,
       SUM(CASE WHEN i_is_current = 'Y' THEN 1 ELSE 0 END) AS current_rows
FROM item;

SELECT sum(ss.ss_ext_sales_price) AS revenue_2002_09
FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk
WHERE d.d_year=2002 AND d.d_moy=9;

SELECT sum(ss.ss_ext_sales_price) AS revenue_2001_06
FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk
WHERE d.d_year=2001 AND d.d_moy=6;

SELECT SUM(cs.cs_ext_sales_price)
FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk
WHERE d.d_moy = 2 AND d.d_year = 2002;

SELECT SUM(cs.cs_ext_sales_price)
FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk
WHERE d.d_moy = 2 AND d.d_year = 2001;

SELECT SUM(cs.cs_net_paid)
FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk
WHERE d.d_moy = 2 AND d.d_year = 2002;

SELECT SUM(cs.cs_net_paid)
FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk
WHERE d.d_moy = 2 AND d.d_year = 2001;

SELECT COUNT(*) AS total_rows,
       COUNT(DISTINCT (ss_ticket_number, ss_item_sk)) AS distinct_ticket_item
FROM store_sales;

SELECT SUM(cs.cs_ext_sales_price) AS ext_sales, SUM(cs.cs_net_paid) AS net_paid, SUM(cs.cs_net_paid_inc_tax) AS net_paid_tax, COUNT(*) AS rows
FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk
WHERE d.d_year = 2000 AND d.d_moy = 12;
